method remove(element: Odd)
    modifies this
    requires Valid()
    requires |s| > 0
    requires element in s
    ensures |s| == |old(s)| - 1
    ensures old(capacity) == capacity
    ensures Valid()
{
    for i: int := 0 to |s|
        invariant 0 <= i <= |s|
        invariant forall k :: 0 <= k < i ==> s[k] != element
    {
        if s[i] == element
        {
            s := s[..i] + s[i + 1..];
            break;
        }
    }
}

